<?php $days = [1 => 'Lunes', 'Martes', 'Miércoles', 'Jueves', 'Viernes', 'Sábado', 'Domingo']; ?>
<section class="admin-page-head"><div><p class="admin-kicker"><?= e($branch->code) ?></p><h1><?= e($branch->name) ?></h1><p><?= e($branch->address ?? 'Dirección pendiente de registrar') ?></p></div><div class="admin-head-actions"><span class="admin-status <?= $branch->active ? 'is-active' : '' ?>"><?= $branch->active ? 'Activa' : 'Inactiva' ?></span><?php if ($capabilities['branches.edit'] ?? false): ?><a class="admin-secondary-button" href="/admin/branches/edit?id=<?= e($branch->id) ?>">Editar</a><?php endif ?></div></section>
<div class="admin-grid-2 admin-grid-align-start"><section class="admin-panel"><h2>Horario regular</h2><?php if ($hours === null): ?><p class="admin-empty">No tienes permiso para consultar horarios.</p><?php elseif ($hours === []): ?><p class="admin-empty">No hay horarios registrados. La sucursal se considera cerrada.</p><?php else: ?><ul class="admin-simple-list"><?php foreach ($hours as $row): ?><li><strong><?= e($days[(int) $row['iso_weekday']] ?? 'Día') ?></strong><span><?= e(substr((string) $row['opens_at'], 0, 5)) ?>–<?= e(substr((string) $row['closes_at'], 0, 5)) ?><?= (int) $row['crosses_midnight'] === 1 ? ' (+1 día)' : '' ?></span></li><?php endforeach ?></ul><?php endif ?></section>
<section class="admin-panel"><h2>Servicios comerciales asociados</h2><?php if ($services === null): ?><p class="admin-empty">No tienes permiso para consultar servicios.</p><?php elseif ($services === []): ?><p class="admin-empty">No hay servicios asociados.</p><?php else: ?><ul class="admin-simple-list"><?php foreach ($services as $service): ?><li><span><strong><?= e($service['name']) ?></strong><small><?= e($service['code']) ?></small></span><span class="admin-status <?= (int) $service['is_active'] === 1 && (int) $service['is_enabled'] === 1 ? 'is-active' : '' ?>"><?= (int) $service['is_enabled'] === 1 ? 'Habilitado' : 'Deshabilitado' ?></span></li><?php endforeach ?></ul><?php endif ?></section></div>
<section class="admin-panel"><h2>Datos de contacto</h2><dl class="admin-definition-grid"><div><dt>Teléfono</dt><dd><?= e($branch->phone ?? 'No registrado') ?></dd></div><div><dt>Correo</dt><dd><?= e($branch->email ?? 'No registrado') ?></dd></div><div><dt>WhatsApp</dt><dd><?= e($branch->whatsapp ?? 'No registrado') ?></dd></div><div><dt>Coordenadas</dt><dd><?= $branch->latitude !== null ? e($branch->latitude . ', ' . $branch->longitude) : 'No registradas' ?></dd></div></dl></section>
